import axios from "axios";
import MaterialTable, { MTableToolbar } from "material-table";
import React, { Component } from "react";
import { connect } from "react-redux";
import { Spinner } from "reactstrap";
import { tokenConfig } from "../../actions/authActions";
import store from "../../store";
import { changePage } from "../../actions/pageActions";
import {
  Checkbox,
  Snackbar,
  MuiAlert,
  Paper,
  Tab,
  Tabs,
  Box
} from "@material-ui/core";
import Typography from "@material-ui/core/Typography";
import { makeStyles } from "@material-ui/core/styles";
class ClientDetail extends Component {
  state = {
    value: ""
  };

  render() {
    return (
      <Paper square>
        <Tabs
          value={this.state.value}
          orientation="vertical"
          indicatorColor="primary"
          textColor="primary"
          onChange={this.handleChange}
          centered
          className={classes.tabs}
        >
          <Tab label="Billing" {...a11yProps(0)} />
          <Tab label="Service Agreements" {...a11yProps(1)} />
          <Tab label="Warranty" {...a11yProps(2)} />
          <Tab label="Reports" {...a11yProps(3)} />
          <Tab label="EU Features" {...a11yProps(4)} />
          <Tab label="Service Agreements" {...a11yProps(5)} />
          <Tab label="Requirements Documents" {...a11yProps(6)} />
        </Tabs>
      </Paper>
    );
  }
}

const mapStateToProps = state => ({
  auth: state.auth
});

export default connect(mapStateToProps, { changePage })(ClientDetail);
